{
  "requirements": [
    {
      "text": "The system shall ensure that no member can borrow more than 5 books simultaneously.",
      "kaos_level": "operational",
      "rationale": "This limits the risk of overwhelming the system with excessive transactions and ensures fair access to resources."
    },
    {
      "text": "The system shall automatically track and notify members of overdue books within 24 hours of the due date.",
      "kaos_level": "tactical",
      "rationale": "Prompt notifications enhance accountability and encourage timely returns, reducing the risk of resource unavailability."
    },
    {
      "text": "The system shall maintain real-time inventory status of all books to prevent double borrowing.",
      "kaos_level": "tactical",
      "rationale": "Real-time tracking reduces the risk of confusion or errors in book availability, enhancing reliability."
    },
    {
      "text": "The system shall provide a backup mechanism to recover all transaction data in case of a failure.",
      "kaos_level": "strategic",
      "rationale": "Data recovery ensures continued operation and safety of member information and borrowing history."
    },
    {
      "text": "The system shall allow librarians to revoke borrowing privileges for members with outstanding overdue books.",
      "kaos_level": "tactical",
      "rationale": "This enforcement helps maintain system integrity and promotes responsible usage among members."
    },
    {
      "text": "The system shall implement a user authentication process to ensure only registered members can access borrowing features.",
      "kaos_level": "operational",
      "rationale": "Authentication safeguards member data and reduces the risk of unauthorized access to the system."
    },
    {
      "text": "The system shall log all transactions, including borrow and return actions, for audit purposes.",
      "kaos_level": "tactical",
      "rationale": "Transaction logging enhances accountability and allows for performance monitoring, contributing to system reliability."
    }
  ]
}
